{"path":"C:\Users\spay\Documents\_tabs_report.py","content":""""Read Yandex Browser open tabs (tail of session file) + titles from History DB."""
import os, re, sqlite3, shutil, tempfile, datetime

ROOT = r"C:\Users\spay\AppData\Local\Yandex\YandexBrowser\User Data"
URL_RE = re.compile(r"https?://[A-Za-z0-9\-\._~:/?#\[\]@!$&'()*+,;=%]{4,250}")
SKIP_EXT = re.compile(r"\.(png|jpg|jpeg|gif|svg|webp|css|js|mjs|woff2?|ico|xml|json|txt)(\?|$)", re.I)
SKIP_HOST = ("googlesyndication", "googleadservices", "doubleclick", "schema.org",
             "accounts.google.com/RotateCookiesPage", "ogs.google.com", "gstatic", "googleapis.com/manifest")


def tail_urls(path, tail_bytes=400_000):
    with open(path, "rb") as f:
        f.seek(0, os.SEEK_END)
        size = f.tell()
        f.seek(max(0, size - tail_bytes))
        raw = f.read()
    txt = raw.decode("utf-16-le", errors="ignore")
    out, seen = [], set()
    for m in URL_RE.findall(txt):
        u = m.rstrip('.,)\'"')
        if u in seen or SKIP_EXT.search(u) or any(h in u for h in SKIP_HOST):
            continue
        seen.add(u)
        out.append(u)
    return out


def history_titles(profile_dir):
    hist = os.path.join(profile_dir, "History")
    if not os.path.exists(hist):
        return {}
    tmp = os.path.join(tempfile.gettempdir(), "yandex_hist_%s" % os.getpid())
    shutil.copy2(hist, tmp)
    titles, visits = {}, {}
    try:
        con = sqlite3.connect(tmp)
        cur = con.cursor()
        for url, title, lv in cur.execute(
            "SELECT url, title, last_visit_time FROM urls"
        ):
            if title:
                titles.setdefault(url, title)
            if lv:
                visits[url] = lv
        con.close()
    except Exception as e:
        print("  (history read failed: %s)" % e)
    finally:
        try:
            os.remove(tmp)
        except OSError:
            pass
    return titles, visits


def fmt_chrome_time(v):
    try:
        return datetime.datetime(1601, 1, 1) + datetime.timedelta(microseconds=v)
    except Exception:
        return None


for prof in ("Profile 2", "Profile 1", "Default"):
    pdir = os.path.join(ROOT, prof)
    sess = os.path.join(pdir, "Sessions")
    if not os.path.isdir(sess):
        continue
    cands = sorted(
        (os.path.join(sess, n) for n in os.listdir(sess) if n.startswith("Session_")),
        key=os.path.getmtime, reverse=True)
    if not cands:
        continue
    newest = cands[0]
    print("=== %s | %s | modified %s ===" % (
        prof, os.path.basename(newest),
        datetime.datetime.fromtimestamp(os.path.getmtime(newest)).strftime("%Y-%m-%d %H:%M:%S")))
    urls = tail_urls(newest)
    titles, visits = history_titles(pdir)
    rows = []
    for u in urls:
        t = titles.get(u)
        if not t:
            # fallback match on netloc+path
            key = u.split('#')[0]
            for hu, ht in titles.items():
                if hu.split('#')[0].rstrip('/') == key.rstrip('/'):
                    t = ht
                    break
        rows.append((visits.get(u, 0), t or "(no title)", u))
    rows.sort(reverse=True)
    for lv, t, u in rows[:45]:
        d = fmt_chrome_time(lv)
        ds = d.strftime("%m-%d %H:%M") if d else "        "
        short = u if len(u) <= 95 else u[:92] + "..."
        print("  %s | %-58s | %s" % (ds, t[:58], short))
    print()
"}
